INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('C9CE4DAF-1CCC-48F7-B23E-0A1956BBD934', N'UDCPS304/25', N'Uniones doble clamp con junta AISI 304 (2 1/2")', N'Las uniones clamp son uniones sanitarias utilizadas en la industria alimenticia y farmacéutica. Fáciles de armar y desarmar. Están compuestas por dos manguitos clamp, una junta y una abrazadera. También se pueden utilizar tapas ciegas para inhabilitar la conexión. Material: AISI 304 Todos los precios publicados incluyen el IVA. Las medidas disponibles y sus correlaciones con los manguitos y abrazaderas puede consultarlas en la "guía de medidas" o en la ficha técnica.', 'EC94368B-B305-49FC-B752-753EEA7AD324', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.460, N'Medida: 2 1/2"', 25.81, 15.49, 5.000, 10.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.7847810', NULL);
