INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('8C7014AF-C734-4840-808D-0C8542547012', N'BVMF304-038', N'Llavín esférico macho-hembra NPT AISI 304 (3/8")', N'El llavín esférico es una llave de paso. Es una válvula esférica más pequeña, con conexión rosca hembra NPT en un extremo y conexión rosca macho NPT en el otro. Material: AISI 304 Medidas disponibles: Llavín esférica macho-hembra 1/4" Llavín esférica macho-hembra 3/8" Todos los precios publicados incluyen el IVA.', '748C91AA-ABF7-4564-B865-63251B0E1855', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.100, N'Medida: 3/8"', 17.86, 10.72, 5.000, 10.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.0811614', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('0F8E5752-9AF3-4B11-989F-0E1A5EA8891D', N'CRCC30415/12', N'Cruz Clamp (1 1/4")', N'Las cruces son conectores que permiten unir o separar el flujo de una cañería. Son producidas masivamente, siendo cada cruz idéntica a cualquier otra de la misma medida. Material: AISI 304 Todos los precios publicados incluyen el IVA . Consulte la ficha técnica para más información y medidas del producto.', '03822C6F-9563-4099-9075-E1C49EF5BC32', 5, N'UNIDAD', N'', NULL, N'', NULL, NULL, NULL, 0.430, N'Medida: 1 1/4"', 54.86, 32.92, 2.000, 3.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.6670375', NULL);
