INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('83489734-5727-4019-A239-2A4BDE7ADD72', N'JCEPDM80', N'Junta clamp de silicona (8")', N'Las juntas clamp son un componente de las uniones clamp. Las mismas se utilizan para conectar cañerías, válvulas u otros accesorios entre sí. Las juntas se colocan entre dos manguitos y son comprimidas por la abrazadera para lograr un sellado óptimo. De esta forma, se evitan pérdidas de fluido a través de la unión. Las medidas disponibles y sus correlaciones con los manguitos y abrazaderas puede consultarlas en la "guía de medidas" o en la ficha técnica.', '03822C6F-9563-4099-9075-E1C49EF5BC32', 5, N'UNIDAD', N'', NULL, N'', NULL, NULL, NULL, 0.020, N'Medida: 8"', 12.54, 7.52, 5.000, 10.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.8402394', NULL);
