INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('9799380C-1494-459E-AECB-4298F3CA9DC5', N'TC316BPE/40', N'Tapa clamp AISI 316 - Linea Cleanox (4")', N'Las tapas clamp son un componente de las uniones clamp y se utilizan para inhabilitar una conexión clamp. Todos los los productos de la línea Cleanox, por su material y su pulido interior de Ra ≤ 0.8µm, son especialmente aptos para ser ser utilizados en la industria farmacéutica y alimenticia. Material: AISI 316. Todos los precios publicados incluyen el IVA.', '03822C6F-9563-4099-9075-E1C49EF5BC32', 5, N'UNIDAD', N'AISI 316', NULL, N'', NULL, NULL, NULL, 0.080, N'Medida: 4"', 29.50, 17.70, 1.000, 2.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:35.9164878', NULL);
