INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('5ED10EB7-AF62-4052-AC14-45143FAA372F', N'sin2', N'Válvula Mariposa sanitaria mecanizada Soldar AISI 304 (1 1/2", 2 posiciones)', N'Las válvulas mariposa sanitarias son utilizadas en las industrias alimenticia y farmacéutica por su alta versatilidad, su condición sanitaria y su bajo coste. Son válvulas de apertura, cierre y regulación (dependiendo de su maneta). Todos los precios publicados incluyen el IVA. Para más información técnica y de medidas sobre este producto, descargue la fich mecanizadaa técnica.', '8A046953-6483-49C9-A2C3-0E7B58CF9356', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 1.130, N'Medida: 1 1/2"; Maneta: 2 posiciones', 0.47, 0.28, 0.000, 0.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.6119819', NULL);
