INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('E19A0DF0-AE4B-44B2-AF00-46851EC7FB90', N'UDCPS304/05', N'Uniones doble clamp con junta AISI 304 (1/2" miniclamp)', N'Las uniones clamp son uniones sanitarias utilizadas en la industria alimenticia y farmacéutica. Fáciles de armar y desarmar. Están compuestas por dos manguitos clamp, una junta y una abrazadera. También se pueden utilizar tapas ciegas para inhabilitar la conexión. Material: AISI 304 Todos los precios publicados incluyen el IVA. Las medidas disponibles y sus correlaciones con los manguitos y abrazaderas puede consultarlas en la "guía de medidas" o en la ficha técnica.', 'EC94368B-B305-49FC-B752-753EEA7AD324', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.360, N'Medida: 1/2" miniclamp', 17.75, 10.65, 0.000, 0.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.7837785', NULL);
