INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('EA6704E4-CEB3-4CA6-B753-5A692C5430D9', N'VDCC304/15', N'Válvula Diafragma simple asiento 316L - Linea Cleanox (1 1/2")', N'Las válvulas diafragma sanitarias son válvulas que permiten una gran regulación del caudal. Debido a esto y su condición sanitaria es que son extensamente utilizadas en la industria farmacéutica. Material: AISI 316L Medidas disponible: Válvula diafragma1" conexión Clamp, asiento simple. AISI 316 Válvula diafragma1 1/2" conexión Clamp, asiento simple. AISI 316 Todos los precios publicados incluyen el IVA.', '77D88D89-0C09-4959-8FFB-C27BCF8DB97E', 5, N'UNIDAD', N'', NULL, N'', NULL, NULL, NULL, 1.700, N'Medida: 1 1/2"', 118.48, 71.09, 2.000, 4.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.2218610', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('18C21B6F-5C29-4944-BF81-5A7683522AA2', N'ORSV', N'Oring para Válvula Toma muestra marca JEKLO', N'¡IMPORTANTE! Los repuestos de esta sección son exclusivos para productos marca Jeklo. Debido a sus medidas o características, NO son intercambiables con otras marcas. En caso de adquirirlo para un producto que no sea marca Jeklo, no se aceptarán devoluciones. Material: Silicona Todos los precios publicados incluyen el IVA.', 'E991322B-BE91-4105-B9EF-3D7A06CE0DB3', 3, N'UNIDAD', N'', NULL, N'', NULL, NULL, NULL, 0.010, N'', 2.03, 1.22, 42.000, 84.000, 1, 1, 0, 1, N'', N'', '2026-10-20T23:17:36.2867686', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('3573B66E-A8DA-47F7-A6B4-5ABED13AACE1', N'VSPV304-20/15B', N'Válvula de Alivio para sobrepresión y vacío regulable Clamp AISI 304 (1 1/2", 0.5-2 bar)', N'Las válvulas de alivio o seguridad son válvulas que liberan el exceso de presión dentro de un tanque. También, permiten el ingreso de aire del exterior si la presión interna baja por debajo de la presión seteada. Material: AISI 304 Todos los precios publicados incluyen el IVA. Para más información técnica sobre este producto, descargue la ficha técnica.', '0683AE1D-A7F2-493A-9328-638EE88A3CA0', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.480, N'Medida: 1 1/2"; Presion: 0.5-2 bar', 112.71, 67.63, 10.000, 21.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.5564696', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('A3A9D078-1965-42BF-81B0-5AC279F2317B', N'JUD20', N'Junta de silicona para union danesa (2")', N'Las juntas danesas son un componente de las uniones danesas. Las mismas se utilizan para conectar cañerías, válvulas u otros accesorios entre sí. Las juntas se colocan entre los dos manguitos y son comprimidas por la tuerca para lograr un sellado óptimo. De esta forma, se evitan pérdidas de fluido a través de la unión. Material: Silicona Medidas disponibles: Juntas Unión Danesa 1" Juntas Unión Danesa 1 1/4" Juntas Unión Danesa 1 1/2" Juntas Unión Danesa 2" Todos los precios publicados incluye...', '1CE56C8F-C0ED-4144-B3F7-48C63D3AC189', 5, N'UNIDAD', N'', NULL, N'', NULL, NULL, NULL, NULL, N'Medida: 2"', 0.73, 0.44, 2.000, 4.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.7307278', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('41027FAA-7FFC-4498-B8F1-5AF739B6B7D0', N'VD2CC316-07', N'Válvula diafragma doble asiento 316L - Linea Cleanox (3/4")', N'Las válvulas diafragma doble asiento son válvulas sanitarias que permiten una gran regulación de caudal. Son extensamente utilizadas en la industria farmacéutica y alimenticia. Material de construcción : AISI 316L Conexión : Clamp Todos los precios publicados incluyen el IVA.', '77D88D89-0C09-4959-8FFB-C27BCF8DB97E', 5, N'UNIDAD', N'', NULL, N'', NULL, NULL, NULL, 2.520, N'Medida: 3/4"', 163.75, 98.25, 2.000, 4.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:35.9144661', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('D17C8A14-44CB-41E2-B4F8-5B18EF088EA4', N'A554E1000-12', N'Caño redondo Estructural A554 AISI 304L (1 1/4", 1,65mm, 1000mm)', N'Los caños norma A554 son caños redondos con costura, con pulido exterior espejo. Se utilizan en aplicaciones estructurales en donde la estética y las resistencias mecánicas y a la corrosión son apreciadas.', '7E14896F-433C-4635-94F0-01BB030B02AD', 1, N'UNIDAD', N'AISI 304L', NULL, N'', NULL, NULL, NULL, 1.250, N'Medida: 1 1/4"; Espesor: 1,65mm; Largo: 1000mm', 9.98, 5.99, 0.000, 0.000, 0, 1, 0, 1, N'', N'', '2026-10-20T23:17:36.1763845', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('3D7FF6D4-60B8-45DE-B656-5B954D09FC5A', N'VMMNCC304/20', N'Válvula Mariposa sanitaria con actuador neumático AISI 304 (2")', N'Las válvulas mariposa sanitarias con actuador neumático son utilizadas para la automatización de procesos en la industria alimenticia y farmacéutica. El actuador permite la apertura y cierre de la válvula en forma remota. Material: AISI 304 Medidas disponibles: Válvula mariposa sanitaria con actuador neumático 1 ½" Válvula mariposa sanitaria con actuador neumático 2" Por otras medidas consulte a su asesor comercial. Todos los precios publicados incluyen el IVA. Para más información sobre este...', '38DC800A-FD18-439B-98E3-B5B047409715', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 6.000, N'Medida: 2"', 314.00, 188.40, 0.000, 0.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.2867686', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('DEDD67C8-7111-4AED-A97A-5BA693B65926', N'VE3CCC30415', N'Valvula esferica 3 cuerpos clamp sanitaria AISI 304 (1 1/2")', N'Las válvulas esféricas de tres cuerpos proporcionan mayor versatilidad y facilidad de mantenimiento en comparación con la válvula de dos cuerpos debido a la presencia de una pieza intermedia en la válvula de tres cuerpos, lo que la hace adecuada para aplicaciones donde se valora un mayor control del flujo y una mayor facilidad de mantenimiento y reparación, ya que es posible retirar el cuerpo central sin tener que desmontar toda la válvula. Material: AISI 304 Conexión: Clamp Medidas disponibl...', '1CE754D0-DFE0-4BB7-841A-DDE8853EDD16', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 1.360, N'Medida: 1 1/2"', 219.74, 131.84, 1.000, 2.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.1300689', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('F9691C8B-4E5E-4D03-AF55-5BC8C7DF17C3', N'CIPR304-10', N'Bocha CIP Rotativa para Soldar AISI 304 (1")', N'Las bocha CIP rotativas son elementos de alta eficiencia que permiten la sanitización de tanques y fermentadores luego de su uso. Material: AISI 304 Todos los precios publicados incluyen el IVA. Consulte la ficha técnica para más información sobre las medidas disponibles y su requerimiento de caudal y presión.', '0683AE1D-A7F2-493A-9328-638EE88A3CA0', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.350, N'Medida: 1"', 51.27, 30.76, 2.000, 4.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.2228648', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('AE1682E4-40AB-4B57-8A50-5C8EC8FEBAA9', N'MCPS304-15/60', N'Manguitos clamp AISI 304 (6")', N'Los Manguitos Clamp son un componente de las uniones clamp. Las mismas se utilizan para conectar cañerías, válvulas u otros accesorios entre sí, soldando uno de sus extremos a la tubería o tanque y conectando el otro mediante una junta y abrazadera. Las medidas disponibles y sus correlaciones en abrazaderas puede consultarlas en la Guía de medidas o en la Ficha Técnica.', '03822C6F-9563-4099-9075-E1C49EF5BC32', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.400, N'Medida: 6"', 33.18, 19.91, 4.000, 8.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.8936597', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('2CBDEA80-B4A8-4D7B-AC62-5EB03DDB28DD', N'CSS304-15/25-90', N'Curva para Soldar 90° AISI 304 (2 1/2")', N'Las curvas o codos son conectores que permiten el desvío a 90° de una cañería. Son producidas masivamente, siendo cada curva idéntica a cualquier otra de la misma medida. Material: AISI 304 Todos los precios publicados incluyen el IVA. Consulte la guía de medidas o la ficha técnica para más información sobre las medidas del producto. DESCARGAR FICHA TÉCNICA', '5814049E-C160-4C42-BB47-80005E458A63', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.360, N'Medida: 2 1/2"', 18.19, 10.91, 18.000, 36.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.8961878', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('853CEFD8-E1BA-4504-838F-5EFD71FBDE01', N'JCEPDM05', N'Junta clamp de silicona (1/2" miniclamp)', N'Las juntas clamp son un componente de las uniones clamp. Las mismas se utilizan para conectar cañerías, válvulas u otros accesorios entre sí. Las juntas se colocan entre dos manguitos y son comprimidas por la abrazadera para lograr un sellado óptimo. De esta forma, se evitan pérdidas de fluido a través de la unión. Las medidas disponibles y sus correlaciones con los manguitos y abrazaderas puede consultarlas en la "guía de medidas" o en la ficha técnica.', '03822C6F-9563-4099-9075-E1C49EF5BC32', 5, N'UNIDAD', N'', NULL, N'', NULL, NULL, NULL, 0.010, N'Medida: 1/2" miniclamp', 0.57, 0.34, 14.000, 29.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.8382332', NULL);
