INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('91CB9459-8EFE-4216-8395-6BCACF35836A', N'TEECCC30415/12', N'Tee clamp AISI 304 (1 1/4")', N'Tee Clamp pulido interior sanitario, pulido exterior espejo. Material: AISI 304.', '03822C6F-9563-4099-9075-E1C49EF5BC32', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.330, N'Medida: 1 1/4"', 27.58, 16.55, 1.000, 2.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.6690617', NULL);
