INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('55F8B244-FFC4-450A-BC2C-6D7DC3DFD43C', N'TEEBPECC316L/07', N'Tee clamp AISI 316L - Linea Cleanox (3/4")', N'Las Tee son conectores que permiten unir o separar el flujo de una cañería. Son producidas masivamente, siendo cada tee idéntica a cualquier otra de la misma medida. Todos los los productos de la línea Cleanox, por su material y su pulido interior de Ra ≤ 0.8 μm, son especialmente aptos para ser ser utilizados en la industria farmacéutica y alimenticia. Material: AISI 316L Todos los precios publicados incluyen el IVA.', '03822C6F-9563-4099-9075-E1C49EF5BC32', 5, N'UNIDAD', N'AISI 316L', NULL, N'', NULL, NULL, NULL, 0.050, N'Medida: 3/4"', 44.26, 26.56, 2.000, 5.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:35.9174903', NULL);
