INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('558720BA-AA48-4A43-AD2A-73E9824A781A', N'JCEPDM25', N'Junta clamp de silicona (2 1/2")', N'Las juntas clamp son un componente de las uniones clamp. Las mismas se utilizan para conectar cañerías, válvulas u otros accesorios entre sí. Las juntas se colocan entre dos manguitos y son comprimidas por la abrazadera para lograr un sellado óptimo. De esta forma, se evitan pérdidas de fluido a través de la unión. Las medidas disponibles y sus correlaciones con los manguitos y abrazaderas puede consultarlas en la "guía de medidas" o en la ficha técnica.', '03822C6F-9563-4099-9075-E1C49EF5BC32', 5, N'UNIDAD', N'', NULL, N'', NULL, NULL, NULL, 0.010, N'Medida: 2 1/2"', 0.94, 0.56, 11.000, 22.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.8392369', NULL);
