INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('0D455713-BB43-40AF-AFBA-861D24E43219', N'CSBPE316L-15/10-90', N'Curva para soldar 90 grados AISI 316 - Linea Cleanox (1")', N'Las curvas o codos son conectores que permiten el desvío a 90° de una cañería. Son producidas masivamente, siendo cada curva idéntica a cualquier otra de la misma medida. Todos los los productos de la línea Cleanox, por su material y su pulido interior de Ra ≤ 0.8 µm, son especialmente aptos para ser ser utilizados en la industria farmacéutica y alimenticia. Material: AISI 316L Todos los precios publicados incluyen el IVA.', '5814049E-C160-4C42-BB47-80005E458A63', 5, N'UNIDAD', N'AISI 316', NULL, N'', NULL, NULL, NULL, 0.400, N'Medida: 1"', 21.63, 12.98, 6.000, 12.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:35.9742015', NULL);
