INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('44AA70B9-8618-46AF-A406-89FF81BEC150', N'VD2CC316/15', N'Válvula diafragma doble asiento 316L - Linea Cleanox (1 1/2")', N'Las válvulas diafragma doble asiento son válvulas sanitarias que permiten una gran regulación de caudal. Son extensamente utilizadas en la industria farmacéutica y alimenticia. Material de construcción : AISI 316L Conexión : Clamp Todos los precios publicados incluyen el IVA.', '77D88D89-0C09-4959-8FFB-C27BCF8DB97E', 5, N'UNIDAD', N'', NULL, N'', NULL, NULL, NULL, 2.520, N'Medida: 1 1/2"', 318.82, 191.29, 1.000, 2.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:35.9144661', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('171199D5-CF3B-4A0F-81CC-8A7A87AEF3F4', N'VMMCC30420', N'Válvula Mariposa sanitaria mecanizada Clamp AISI 304 (2", 3 posiciones)', N'Las válvulas mariposa sanitarias son utilizadas en las industrias alimenticia y farmacéutica por su alta versatilidad, su condición sanitaria y su bajo coste. Son válvulas de apertura, cierre y regulación (dependiendo de su maneta). Todos los precios publicados incluyen el IVA. Para más información técnica y de medidas sobre este producto, descargue la fich mecanizadaa técnica.', '8A046953-6483-49C9-A2C3-0E7B58CF9356', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 1.790, N'Medida: 2"; Maneta: 3 posiciones', 100.70, 60.42, 2.000, 4.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.6140216', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('02DA73C5-8B1B-4634-93B6-8AEDC75D9272', N'CIPR304-15', N'Bocha CIP Rotativa para Soldar AISI 304 (1 1/2")', N'Las bocha CIP rotativas son elementos de alta eficiencia que permiten la sanitización de tanques y fermentadores luego de su uso. Material: AISI 304 Todos los precios publicados incluyen el IVA. Consulte la ficha técnica para más información sobre las medidas disponibles y su requerimiento de caudal y presión.', '0683AE1D-A7F2-493A-9328-638EE88A3CA0', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.450, N'Medida: 1 1/2"', 68.50, 41.10, 4.000, 7.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.2228648', NULL);
