INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('242491F8-7A2A-4B00-819B-B22DCE79884B', N'MDR40-C50', N'Adaptador Rosca DIN a Clamp - AISI 304 (DN40 a clamp 1,5")', N'Sirve para conectar dos sistemas de unión distintos dentro de una misma línea: Lado 1: Rosca DIN (rosca sanitaria estándar europeo) Lado 2: Tri-Clamp (conexión sanitaria rápida con abrazadera) Esto permite, por ejemplo: Conectar una válvula, bomba o tanque con rosca DIN a una manguera, caño o accesorio con conexión clamp sin modificar la instalación existente.', '03822C6F-9563-4099-9075-E1C49EF5BC32', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.400, N'Medida: DN40 a clamp 1,5"', 43.94, 26.36, 2.000, 4.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:35.8421284', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('A38E5560-E09C-4F7E-9EAE-B3491D7EF239', N'CSBPE316L-15/15-90', N'Curva para soldar 90 grados AISI 316 - Linea Cleanox (1 1/2")', N'Las curvas o codos son conectores que permiten el desvío a 90° de una cañería. Son producidas masivamente, siendo cada curva idéntica a cualquier otra de la misma medida. Todos los los productos de la línea Cleanox, por su material y su pulido interior de Ra ≤ 0.8 µm, son especialmente aptos para ser ser utilizados en la industria farmacéutica y alimenticia. Material: AISI 316L Todos los precios publicados incluyen el IVA.', '5814049E-C160-4C42-BB47-80005E458A63', 5, N'UNIDAD', N'AISI 316', NULL, N'', NULL, NULL, NULL, 0.400, N'Medida: 1 1/2"', 29.20, 17.52, 6.000, 12.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:35.9742015', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('30A63612-1F83-417F-949B-B45036FABE30', N'TC304/20', N'Tapas clamp AISI 304 (2")', N'Las tapas clamp son un componente de las uniones clamp y se utilizan para inhabilitar una conexión clamp. Las medidas disponibles y sus correlaciones con los manguitos y abrazaderas puede consultarlas en la guía de medidas o en la ficha técnica.', '03822C6F-9563-4099-9075-E1C49EF5BC32', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.130, N'Medida: 2"', 5.48, 3.29, 8.000, 15.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.7868791', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('DB8A3818-6811-4476-B8B4-B4D47EA8C99D', N'A554E1000-10', N'Caño redondo Estructural A554 AISI 304L (1", 1,65mm, 1000mm)', N'Los caños norma A554 son caños redondos con costura, con pulido exterior espejo. Se utilizan en aplicaciones estructurales en donde la estética y las resistencias mecánicas y a la corrosión son apreciadas.', '7E14896F-433C-4635-94F0-01BB030B02AD', 1, N'UNIDAD', N'AISI 304L', NULL, N'', NULL, NULL, NULL, 1.000, N'Medida: 1"; Espesor: 1,65mm; Largo: 1000mm', 8.05, 4.83, 0.000, 0.000, 0, 1, 0, 1, N'', N'', '2026-10-20T23:17:36.1763845', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('F73CEA8B-F05A-4830-8F7C-B531F7E0FD4D', N'VMMPS30425', N'Válvula Mariposa sanitaria mecanizada Soldar AISI 304 (2 1/2", 2 posiciones)', N'Las válvulas mariposa sanitarias son utilizadas en las industrias alimenticia y farmacéutica por su alta versatilidad, su condición sanitaria y su bajo coste. Son válvulas de apertura, cierre y regulación (dependiendo de su maneta). Todos los precios publicados incluyen el IVA. Para más información técnica y de medidas sobre este producto, descargue la fich mecanizadaa técnica.', '8A046953-6483-49C9-A2C3-0E7B58CF9356', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 2.000, N'Medida: 2 1/2"; Maneta: 2 posiciones', 102.18, 61.31, 4.000, 8.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.6129899', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('31D6BA71-B83E-4E22-B2FC-B548E79D5C70', N'VMPS304-05', N'Visor Tubular para Soldar AISI 304 (1/2")', N'Los visores tubulares permiten la inspección visual del interior de una cañería. Material de construcción: AISI 304 Conexión: para soldar Medidas disponibles: Visor tubular1/2" para soldar Todos los precios publicados incluyen el IVA.', 'A0716882-7A04-4EA4-AD67-113F2DB4444F', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 1.050, N'Medida: 1/2"', 108.28, 64.97, 2.000, 3.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.1804269', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('CD4CDDEC-F957-4AA3-BFA7-B593DAF64EF6', N'MCPS304-15/25', N'Manguitos clamp AISI 304 (2 1/2")', N'Los Manguitos Clamp son un componente de las uniones clamp. Las mismas se utilizan para conectar cañerías, válvulas u otros accesorios entre sí, soldando uno de sus extremos a la tubería o tanque y conectando el otro mediante una junta y abrazadera. Las medidas disponibles y sus correlaciones en abrazaderas puede consultarlas en la Guía de medidas o en la Ficha Técnica.', '03822C6F-9563-4099-9075-E1C49EF5BC32', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.100, N'Medida: 2 1/2"', 5.64, 3.38, 10.000, 19.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.8422618', NULL);
