INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('6E38F177-E0C5-4BBE-883F-BA487E2408B5', N'STFCPS500', N'Sello para tapa redonda alta presion (500 mm.)', N'¡IMPORTANTE! Los repuestos de esta sección son exclusivos para productos marca Jeklo. Debido a sus medidas o características, NO son intercambiables con otras marcas. En caso de adquirirlo para un producto que no sea marca Jeklo, NO se aceptarán devoluciones. Todos los precios publicados incluyen el IVA.', '9C1C1B9F-C000-4314-B89E-E164A2362F8F', 5, N'UNIDAD', N'', NULL, N'', NULL, NULL, NULL, 0.170, N'Medida: 500 mm.', 27.10, 16.26, 2.000, 3.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.0821672', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('08686840-863D-45AE-A6D1-BB219482475F', N'KITOXIG', N'Kit de oxigenación AISI 304', N'Los kits de oxigenación Jeklo están diseñados para oxigenar el mosto previo al ingreso del fermentador. De esta forma, se logra una fermentación más sana y veloz. El kit debe colocarse a la salida del intercambiador de placas. Material: AISI 304 Medidas disponibles: 1 ½” Conexión: Clamp Todos los precios publicados incluyen el IVA. Para más información sobre este producto, descargue la ficha técnica.', 'AFA691ED-D0BC-4704-9DB3-5F4F8E77F843', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 4.700, N'', 464.83, 278.90, 2.000, 4.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.5066477', NULL);
