INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('E89086EC-6DBC-411C-A91C-BC96AAEB891C', N'UDCT304/40', N'Unión doble Clamp con Tapa AISI 304 (4")', N'Las uniones clamp son uniones sanitarias utilizadas en la industria alimenticia y farmacéutica. Fáciles de armar y desarmar. Las uniones con tapa están compuestas por un manguito clamp, una junta, una abrazadera y una tapa. Material: AISI 304 Todos los precios publicados incluyen el IVA. Las medidas disponibles y sus correlaciones con los manguitos y abrazaderas puede consultarlas en la "guía de medidas" o en la ficha técnica.', 'EC94368B-B305-49FC-B752-753EEA7AD324', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 1.260, N'Medida: 4"', 47.86, 28.72, 8.000, 15.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.7868791', NULL);
