INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('C2E44DFD-4B37-42E9-9523-C62A38D5B0F0', N'TEEBPEPS316L/07', N'Tee soldar AISI 316L - Linea Cleanox (3/4")', N'Las Tee son conectores que permiten unir o separar el flujo de una cañería. Son producidas masivamente, siendo cada tee idéntica a cualquier otra de la misma medida. Todos los los productos de la línea Cleanox, por su material y su pulido interior de Ra ≤ 0.8 μm, son especialmente aptos para ser ser utilizados en la industria farmacéutica y alimenticia. Material: AISI 316L Todos los precios publicados incluyen el IVA.', '5814049E-C160-4C42-BB47-80005E458A63', 5, N'UNIDAD', N'AISI 316L', NULL, N'', NULL, NULL, NULL, 0.050, N'Medida: 3/4"', 25.20, 15.12, 15.000, 30.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:35.8441740', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('E240500E-1EB8-44C3-A384-C64A45029C75', N'PC250-0.25-316', N'Piedra difusora AISI 316 0.5 (250mm)', N'Las piedras difusoras permiten la inyección de un gas en pequeñas partículas en un líquido, logrando su incorporación en el mismo. Están disponibles en conexión clamp de 50,5mm, siendo la conexión para gas 1/4" NPT. Material de construcción: Conector AISI 316; piedra de titanio. Medidas disponibles: Piedra difusora 2 µm 100mm 1/4NPT Clamp 50mm AISI 316 Piedra difusora 2 µm 150mm 1/4NPT Clamp 50mm AISI 316 Piedra difusora 2 µm 250mm 1/4NPT Clamp 50mm AISI 316 Piedra difusora 2 µm 400mm 1/4NPT ...', 'AFA691ED-D0BC-4704-9DB3-5F4F8E77F843', 5, N'UNIDAD', N'AISI 316', NULL, N'', NULL, NULL, NULL, 0.220, N'Medida: 250mm', 314.41, 188.65, 0.000, 0.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.4499816', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('1BD295D5-7BC2-4B5F-8723-C64B8D56912F', N'VMMSPS30410', N'Válvulas Mariposa Sandwich sanitarias mecanizadas AISI 304 (1")', N'Las válvulas mariposa sandwich mecanizada son utilizadas en las industrias alimenticia y farmacéutica por su alta versatilidad, su condición sanitaria y su bajo coste. Son válvulas de apertura, cierre y regulación (dependiendo de su maneta). Son de fácil montaje y desmontaje. Material: AISI 304 Todos los precios publicados incluyen el IVA.', '8A046953-6483-49C9-A2C3-0E7B58CF9356', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 1.960, N'Medida: 1"', 76.53, 45.92, 1.000, 2.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.5594727', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('142E3924-5EF7-4218-BD47-C68FC3CC9615', N'CL304226-200', N'Cartucho para Filtro conexión 226, AISI 304 (En L, 200)', N'Cartucho para carcasas de Filtro conexión sanitaria 226. A menor micronaje, mayor la retención. Material: AISI 304 y juntas de silicona. Conexión disponible: Conexiones externas clampeadas de 1 1/2" (OD 50.5 mm). Todos los precios publicados incluyen el IVA.', 'AFA691ED-D0BC-4704-9DB3-5F4F8E77F843', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.900, N'Modelo: En L; Micronaje: 200', 226.17, 135.70, 3.000, 6.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:35.8441740', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('E713C090-D530-4EB2-A3E7-C6C68C10F8B2', N'VMMPSRD30420', N'Válvula Mariposa mecanizada DIN / SOLDAR AISI 304 (DN 50)', N'La válvula mariposa mecanizada es un tipo de válvula que se utiliza para regular el flujo de líquidos en tuberías. Tiene un disco que gira en torno a un eje, que se encuentra en el centro de la válvula. Al girar el disco, se puede controlar el flujo de líquido a través de la tubería. La designación "DIN DN 50" se refiere al tamaño y al tipo de la conexión de la válvula. "DIN" es la norma alemana que establece las especificaciones técnicas de la válvula, mientras que "DN 50" se refiere al diám...', '8A046953-6483-49C9-A2C3-0E7B58CF9356', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 1.500, N'Medida: DN 50', 97.76, 58.66, 4.000, 8.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.1300689', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('AF8AA5D1-D3F8-4531-9E7C-C7B9162F6326', N'SCR304/10', N'Soporte Redondo para cano AISI 304 (1")', N'Los soportes para caño tienen la función de fijar el caño en una posición. Esto se logra soldando uno de los extremos del soporte mientras el otro extremo sujeta al caño en su posición. Material: AISI 304 Medidas disponibles: Soporte Redondo1" AISI 304 Soporte Redondo1 1/2" AISI 304 Todos los precios publicados incluyen el IVA. Para más información sobre este producto consulte la ficha técnica.', '33414CC0-7A59-4A00-A6B9-E0308F4BF53E', 1, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.900, N'Medida: 1"', 4.10, 2.46, 12.000, 24.000, 0, 1, 0, 1, N'', N'', '2026-10-20T23:17:36.3952220', NULL);
