INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('E9A5EFFF-59BF-4600-8CE1-C8FE6B068EFE', N'CRCC30415/20', N'Cruz Clamp (2")', N'Las cruces son conectores que permiten unir o separar el flujo de una cañería. Son producidas masivamente, siendo cada cruz idéntica a cualquier otra de la misma medida. Material: AISI 304 Todos los precios publicados incluyen el IVA . Consulte la ficha técnica para más información y medidas del producto.', '03822C6F-9563-4099-9075-E1C49EF5BC32', 5, N'UNIDAD', N'', NULL, N'', NULL, NULL, NULL, 0.440, N'Medida: 2"', 73.14, 43.88, 2.000, 3.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.6680587', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('014E4478-5D7C-49A0-AB64-C91DC493A768', N'CDIN304/50', N'Capelina rosca DIN AISI 304 50 con cadena (DN 50)', N'Las capelinas DIN cumplen la función de tapón ciego. Las mismas deben roscarse a la unión para lograr el cierre. Tipo de conexión: DIN DN 50 Material: AISI 304 Todos los precios publicados incluyen el IVA.', 'F25A7A52-DFFB-414B-9D73-E779E07F70D9', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.800, N'Medida: DN 50', 28.37, 17.02, 10.000, 20.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.1794242', NULL);
