INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('203E1076-882E-4813-AA0D-DA86737B1461', N'JDINSIL/10', N'Junta DIN Silicona (DN 25)', N'Las juntas DINs son un componente de las uniones DINs. Las mismas se utilizan para conectar cañerías, válvulas u otros accesorios entre sí. Las juntas se colocan entre los dos manguitos y son comprimidas por la tuerca para lograr un sellado óptimo. De esta forma, se evitan pérdidas de fluido a través de la unión. Tipo de conexión: DIN DN 32 Material: Silicona Todos los precios publicados incluyen el IVA.', '1CE56C8F-C0ED-4144-B3F7-48C63D3AC189', 5, N'UNIDAD', N'', NULL, N'', NULL, NULL, NULL, 0.010, N'Medida: DN 25', 0.47, 0.28, 7.000, 14.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.1794242', NULL);
