INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('A3F02AD4-A14E-42FA-A290-E88955507FC5', N'TC304/40', N'Tapas clamp AISI 304 (4")', N'Las tapas clamp son un componente de las uniones clamp y se utilizan para inhabilitar una conexión clamp. Las medidas disponibles y sus correlaciones con los manguitos y abrazaderas puede consultarlas en la guía de medidas o en la ficha técnica.', '03822C6F-9563-4099-9075-E1C49EF5BC32', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.590, N'Medida: 4"', 16.72, 10.03, 14.000, 28.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.8371526', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('05D943C0-DD12-4238-80AA-E8CC95197238', N'VPMER304/05', N'Válvula Toma muestra Esférica NPT AISI 304 (1/2")', N'Las válvulas toma muestra son utilizadas para tomar muestras de un tanque, barrica o recipiente sin comprometer el producto en el interior del mismo. Este producto es utilizado especialmente en barricas. Material: AISI 304 Conexión disponible: rosca NPT 1/2" Todos los precios publicados incluyen el IVA. Para más información sobre este producto, descargue la ficha técnica.', '748C91AA-ABF7-4564-B865-63251B0E1855', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.150, N'Medida: 1/2"', 28.64, 17.18, 0.000, 0.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.1804269', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('277F2F50-4ABC-4289-A6EF-E930AD9F40AD', N'JUD40', N'Junta de silicona para union danesa (4")', N'Las juntas danesas son un componente de las uniones danesas. Las mismas se utilizan para conectar cañerías, válvulas u otros accesorios entre sí. Las juntas se colocan entre los dos manguitos y son comprimidas por la tuerca para lograr un sellado óptimo. De esta forma, se evitan pérdidas de fluido a través de la unión. Material: Silicona Medidas disponibles: Juntas Unión Danesa 1" Juntas Unión Danesa 1 1/4" Juntas Unión Danesa 1 1/2" Juntas Unión Danesa 2" Todos los precios publicados incluye...', '1CE56C8F-C0ED-4144-B3F7-48C63D3AC189', 5, N'UNIDAD', N'', NULL, N'', NULL, NULL, NULL, NULL, N'Medida: 4"', 1.20, 0.72, 5.000, 10.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.7307278', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('6B018CBE-0073-48B0-A1E5-E95F8DC6E293', N'VMMPS30415', N'Válvula Mariposa sanitaria mecanizada Soldar AISI 304 (1 1/2", 3 posiciones)', N'Las válvulas mariposa sanitarias son utilizadas en las industrias alimenticia y farmacéutica por su alta versatilidad, su condición sanitaria y su bajo coste. Son válvulas de apertura, cierre y regulación (dependiendo de su maneta). Todos los precios publicados incluyen el IVA. Para más información técnica y de medidas sobre este producto, descargue la fich mecanizadaa técnica.', '8A046953-6483-49C9-A2C3-0E7B58CF9356', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 1.210, N'Medida: 1 1/2"; Maneta: 3 posiciones', 70.10, 42.06, 11.000, 22.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.6119819', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('BF9F2892-3705-4341-A312-EA19F21D0DAC', N'VMMSPS30412', N'Válvulas Mariposa Sandwich sanitarias mecanizadas AISI 304 (1 1/4")', N'Las válvulas mariposa sandwich mecanizada son utilizadas en las industrias alimenticia y farmacéutica por su alta versatilidad, su condición sanitaria y su bajo coste. Son válvulas de apertura, cierre y regulación (dependiendo de su maneta). Son de fácil montaje y desmontaje. Material: AISI 304 Todos los precios publicados incluyen el IVA.', '8A046953-6483-49C9-A2C3-0E7B58CF9356', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 1.840, N'Medida: 1 1/4"', 76.53, 45.92, 0.000, 0.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.5594727', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('B777261E-6E99-480B-90B1-EA1B5BF0EA5B', N'MDINL304/15', N'Manguito Liso DIN AISI 304 (DN 40)', N'Los manguitos lisos de unión DIN son un componente de las uniones DINs. Las mismas se utilizan para conectar cañerías, válvulas u otros accesorios entre sí, soldando uno de sus extremos a la tubería o tanque y conectando el otro mediante una junta y una tuerca. Tipo de conexión: DIN DN 50 Material: AISI 304 Espesor manguito: 1,65 mm. Todos los precios publicados incluyen el IVA', 'F25A7A52-DFFB-414B-9D73-E779E07F70D9', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.100, N'Medida: DN 40', 7.68, 4.61, 6.000, 12.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:35.8461855', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('1B082ACA-0E5F-4F47-AA9E-EA364C16DD78', N'ORR10', N'Olivas - Racord Rosca NPT para manguera AISI 304 (1" - 1")', N'Las olivas o racord son conectores que permiten conectar una cañería o válvula con rosca NPT a una manguera. Material: AISI 304 Medidas disponibles: Oliva Rosca NPT 1/4" para manguera 1/4" (6,35 mm.) Oliva Rosca NPT 1/2" para manguera 1/2" (12,7 mm.) Oliva Rosca NPT 3/4" para manguera 3/4" (19,05 mm.) Oliva Rosca NPT 1" para manguera 1" (25,4 mm.) Todos los precios publicados incluyen el IVA.', 'E8187749-42B5-4862-B0B8-FC0DDE18F90C', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.130, N'Medida: 1" - 1"', 11.39, 6.83, 2.000, 3.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.2827144', NULL);
