INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('6439E89A-B416-4A32-BA3B-EB022ED81333', N'UDCT304/10', N'Unión doble Clamp con Tapa AISI 304 (1")', N'Las uniones clamp son uniones sanitarias utilizadas en la industria alimenticia y farmacéutica. Fáciles de armar y desarmar. Las uniones con tapa están compuestas por un manguito clamp, una junta, una abrazadera y una tapa. Material: AISI 304 Todos los precios publicados incluyen el IVA. Las medidas disponibles y sus correlaciones con los manguitos y abrazaderas puede consultarlas en la "guía de medidas" o en la ficha técnica.', 'EC94368B-B305-49FC-B752-753EEA7AD324', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.310, N'Medida: 1"', 18.76, 11.26, 8.000, 15.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.7858726', NULL);
