INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('82C01C0E-98CD-4DE3-8BAD-FFC47B6DF785', N'MCPS304-15/80', N'Manguitos clamp AISI 304 (8")', N'Los Manguitos Clamp son un componente de las uniones clamp. Las mismas se utilizan para conectar cañerías, válvulas u otros accesorios entre sí, soldando uno de sus extremos a la tubería o tanque y conectando el otro mediante una junta y abrazadera. Las medidas disponibles y sus correlaciones en abrazaderas puede consultarlas en la Guía de medidas o en la Ficha Técnica.', '03822C6F-9563-4099-9075-E1C49EF5BC32', 5, N'UNIDAD', N'AISI 304', NULL, N'', NULL, NULL, NULL, 0.640, N'Medida: 8"', 51.21, 30.73, 4.000, 9.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.8936597', NULL);
INSERT INTO [dbo].[Productos] ([Id], [CodigoSku], [Nombre], [Descripcion], [CategoriaId], [Tipo], [UnidadMedida], [CalidadAisi], [EspesorMm], [Acabado], [AnchoMm], [LargoMm], [DiametroMm], [PesoUnitarioKg], [Medida], [PrecioBase], [CostoActual], [StockMinimo], [PuntoReposicion], [EsVendible], [EsComprable], [EsFabricable], [Activo], [RutaImagen], [RutaPlanoTecnico], [FechaAlta], [FechaModificacion]) VALUES ('EACDE0D1-1215-4065-B6C3-FFE3EF89D5FB', N'JDINSIL/20', N'Junta DIN Silicona (DN 50)', N'Las juntas DINs son un componente de las uniones DINs. Las mismas se utilizan para conectar cañerías, válvulas u otros accesorios entre sí. Las juntas se colocan entre los dos manguitos y son comprimidas por la tuerca para lograr un sellado óptimo. De esta forma, se evitan pérdidas de fluido a través de la unión. Tipo de conexión: DIN DN 32 Material: Silicona Todos los precios publicados incluyen el IVA.', '1CE56C8F-C0ED-4144-B3F7-48C63D3AC189', 5, N'UNIDAD', N'', NULL, N'', NULL, NULL, NULL, 0.010, N'Medida: DN 50', 0.57, 0.34, 76.000, 151.000, 1, 0, 1, 1, N'', N'', '2026-10-20T23:17:36.1794242', NULL);
